def test_multi_result_chan_slot_var_local_alias_broadcasts(
    go_types_helper,
):
    # `var c, n = g(q)` where g hands q's queue back through a
    # callee-local alias (`r := q; return r, 0`) — the passthrough
    # probe cannot see it, so `c` binds an external queue whose
    # sends broadcast into reads of `q`.
    files = {
        "a.go": "package p\n"
        "func g(q chan int64) (chan int64, int64) {\n"
        "\tr := q\n"
        "\treturn r, 0\n}\n"
        "func F(q chan int64, x int64) int64 {\n"
        "\tvar c, n = g(q)\n"
        "\tc <- x\n"
        "\treturn <-q + n\n}\n"
    }
    snapshot = _snapshot_for(go_types_helper, files)
    result = named_package(
        files, snapshot, ip.summarize_go_package(files, snapshot), "F"
    )
    assert result.available
    assert result.return_dependencies == frozenset({0, 1})


def test_multi_result_chan_slot_received_operation_matches_temporary(
    go_types_helper,
):
    # A chan-chan value from a multi-result call is admitted by
    # `d := <-q`, so a nested receive has the same summary.
    files = {
        "a.go": "package p\n"
        "func G() (chan chan int64, int64) {\n"
        "\treturn make(chan chan int64), 0\n}\n"
        "func F() int64 {\n"
        "\tvar q, n = G()\n"
        "\t_ = n\n"
        "\treturn <-<-q\n}\n"
        "func FTemp() int64 {\n"
        "\tvar q, n = G()\n"
        "\t_ = n\n"
        "\td := <-q\n"
        "\treturn <-d\n}\n"
    }
    snapshot = _snapshot_for(go_types_helper, files)
    summaries = ip.summarize_go_package(files, snapshot)
    nested = named_package(files, snapshot, summaries, "F")
    temporary = named_package(files, snapshot, summaries, "FTemp")
    assert nested.available
    assert temporary.available
    assert nested.return_dependencies == temporary.return_dependencies
    assert nested.effects == temporary.effects
    assert [
        (call.imported, call.arguments, call.result)
        for call in nested.calls
    ] == [
        (call.imported, call.arguments, call.result)
        for call in temporary.calls
    ]


def test_assign_multi_result_chan_slot_reseats(
    go_types_helper,
):
    # `ch, n = g(q)` — the assignment form of the multi-result
    # chan slot: the chan name reseats to the callee's
    # passthrough queue like `ch = g(q)` does. `q` is a buffered
    # LOCAL channel, so a shared-broadcast model cannot reach
    # `{0}` — only the resolved alias carries the send back.
    files = {
        "a.go": "package p\n"
        "func g(q chan int64) (chan int64, int64) { return q, 0 }\n"
        "func F(x int64) int64 {\n"
        "\tq := make(chan int64, 1)\n"
        "\tvar ch chan int64\n"
        "\tch = make(chan int64)\n"
        "\tvar n int64\n"
        "\tch, n = g(q)\n"
        "\tch <- x\n"
        "\treturn <-q + n\n}\n"
    }
    snapshot = _snapshot_for(go_types_helper, files)
    result = named_package(
        files, snapshot, ip.summarize_go_package(files, snapshot), "F"
    )
    assert result.available
    assert result.return_dependencies == frozenset({0})


def test_assign_multi_result_chan_local_alias_broadcasts(
    go_types_helper,
):
    # `ch, n = g(q)` where `g` hands `q`'s queue back through a
    # callee-local alias (`r := q; return r, 0`) — the passthrough
    # probe cannot see it, so `ch` binds external AND the arg's
    # root queue promotes external: `ch <- x` reaches `<-q`.
    files = {
        "a.go": "package p\n"
        "func g(q chan int64) (chan int64, int64) {\n"
        "\tr := q\n"
        "\treturn r, 0\n}\n"
        "func F(x int64) int64 {\n"
        "\tq := make(chan int64, 1)\n"
        "\tvar ch chan int64\n"
        "\tch = make(chan int64)\n"
        "\tvar n int64\n"
        "\tch, n = g(q)\n"
        "\tch <- x\n"
        "\treturn <-q + n\n}\n"
    }
    snapshot = _snapshot_for(go_types_helper, files)
    result = named_package(
        files, snapshot, ip.summarize_go_package(files, snapshot), "F"
    )
    assert result.available
    assert result.return_dependencies == frozenset({0})


