def test_local_channel_alias_chain_and_close(go_types_helper):
    # `ch3 := ch2` resolves through ch2's alias to ch; `close`
    # on an alias admits as the same untracked synchronization
    # fact.
    result = named(
        *unit(
            go_types_helper,
            "func F(x int64) int64 {\n"
            "\tch := make(chan int64)\n"
            "\tch2 := ch\n"
            "\tch3 := ch2\n"
            "\tch3 <- x\n"
            "\tclose(ch3)\n"
            "\treturn <-ch\n}\n",
        )
    )
    assert result.available
    assert result.return_dependencies == frozenset({0})


def test_local_channel_alias_tuple_swap_uses_prestate(go_types_helper):
    # `ch2, ch3 = ch3, ch2` — the swap's alias targets must resolve
    # against the pre-state map: ch2 takes ch3's queue and vice
    # versa, so a send through ch3 lands in ch2's old queue and a
    # read of ch2 observes it.
    result = named(
        *unit(
            go_types_helper,
            "func F(x int64, y int64) int64 {\n"
            "\tch2 := make(chan int64)\n"
            "\tch3 := make(chan int64)\n"
            "\tch2, ch3 = ch3, ch2\n"
            "\tch3 <- x\n"
            "\tch2 <- y\n"
            "\treturn <-ch2 + <-ch3\n}\n",
        )
    )
    assert result.available
    assert result.return_dependencies == frozenset({0, 1})


def test_local_channel_alias_swap_keeps_earlier_alias_queue(
    go_types_helper,
):
    # `c := a; a, b = b, a; c <- x; return <-b` — after the swap a
    # and b each name the other's original queue, and `c` still
    # names a's original queue (the same one `b` now holds): the
    # send lands in the queue `<-b` reads.
    result = named(
        *unit(
            go_types_helper,
            "func F(x int64) int64 {\n"
            "\ta := make(chan int64)\n"
            "\tb := make(chan int64)\n"
            "\tc := a\n"
            "\ta, b = b, a\n"
            "\tc <- x\n"
            "\treturn <-b\n}\n",
        )
    )
    assert result.available
    assert result.return_dependencies == frozenset({0})


def test_local_channel_alias_swap_keeps_queue_contents(
    go_types_helper,
):
    # `a <- x; a, b = b, a; return <-b` — the reseat redirects only
    # the names; the sent value stays in the original queue's slot,
    # which `b` now names.
    result = named(
        *unit(
            go_types_helper,
            "func F(x int64) int64 {\n"
            "\ta := make(chan int64)\n"
            "\tb := make(chan int64)\n"
            "\ta <- x\n"
            "\ta, b = b, a\n"
            "\treturn <-b\n}\n",
        )
    )
    assert result.available
    assert result.return_dependencies == frozenset({0})


def test_chan_parameter_reseat_bare_read_follows_queue(
    go_types_helper,
):
    # `p = q` reseats the parameter's name onto q's queue — a bare
    # `G(p)` argument read surfaces q's queue provenance, not p's.
    files = {
        "a.go": "package p\n"
        "func G(ch chan int64) int64 { return 0 }\n"
        "func F(p, q chan int64) int64 {\n"
        "\tp = q\n"
        "\treturn G(p)\n}\n"
    }
    snapshot = _snapshot_for(go_types_helper, files)
    result = named_package(
        files, snapshot, ip.summarize_go_package(files, snapshot), "F"
    )
    assert result.available
    assert frozenset({1}) in {
        r.deps for r in result.statement_reads
    }


def test_local_channel_alias_closure_call_follows_reseat(
    go_types_helper,
):
    # `h := func() int64 { return <-ch }; ch2 <- y; ch = ch2; h()`
    # — the captured channel name reseated between the literal and
    # the call, so the call reads the queue `ch` names now.
    result = named(
        *unit(
            go_types_helper,
            "func F(x int64, y int64) int64 {\n"
            "\tch := make(chan int64)\n"
            "\tch2 := make(chan int64)\n"
            "\th := func() int64 { return <-ch }\n"
            "\tch2 <- y\n"
            "\tch = ch2\n"
            "\treturn h()\n}\n",
        )
    )
    assert result.available
    assert result.return_dependencies == frozenset({1})


def test_chan_parameter_alias_send_recv(go_types_helper):
    # `ch2 := p` on a `chan` parameter aliases the caller-shared
    # queue: the send records the imported transfer on p's
    # identity and broadcasts into `indirect_writes`, so a later
    # `<-p` (or `<-ch2`) observes it.
    result = named(
        *unit(
            go_types_helper,
            "func F(p chan int64, x int64) int64 {\n"
            "\tch2 := p\n"
            "\tch2 <- x\n"
            "\treturn <-p\n}\n",
        )
    )
    assert result.available
    assert result.effects == "unknown"
    assert result.return_dependencies == frozenset({0, 1})


def test_local_channel_alias_bare_read_follows_source(
    go_types_helper,
):
    # A bare `G(ch2)` read surfaces what the queue may hold — the
    # SOURCE queue's live dep set, not the snapshot the copy
    # froze into `locals_[ch2]`.
    files = {
        "a.go": "package p\n"
        "func F(x int64, y int64) int64 {\n"
        "\tch := make(chan int64)\n"
        "\tch2 := ch\n"
        "\tch <- y\n"
        "\t_ = ch2\n"
        "\treturn x\n}\n"
    }
    snapshot = _snapshot_for(go_types_helper, files)
    summaries = ip.summarize_go_package(files, snapshot)
    result = named_package(files, snapshot, summaries, "F")
    assert result.available
    reads = {r.deps for r in result.statement_reads}
    assert frozenset({1}) in reads


def test_local_channel_len_cap_dep_free(go_types_helper):
    # `len(ch)`/`cap(ch)` — the queue length and capacity are
    # runtime state, not parameter provenance, so the result is
    # dep-free even after `ch <- x`.
    result = named(
        *unit(
            go_types_helper,
            "func F(x int64) int64 {\n"
            "\tch := make(chan int64, 2)\n"
            "\tch <- x\n"
            "\t_ = cap(ch)\n"
            "\treturn int64(len(ch))\n}\n",
        )
    )
    assert result.available
    assert result.return_dependencies == frozenset()


def test_chan_parameter_len_records_transfer(go_types_helper):
    # `len(p)`/`cap(p)` on a `chan` parameter observe the caller's
    # queue — each records an imported transfer on p's identity
    # (effects unknown) while the result stays dep-free.
    result = named(
        *unit(
            go_types_helper,
            "func F(p chan int64) int64 {\n"
            "\treturn int64(len(p)) + int64(cap(p))\n}\n",
        )
    )
    assert result.available
    assert result.return_dependencies == frozenset()
    assert result.effects == "unknown"
    assert len(result.calls) == 2
    assert {t.imported for t in result.calls} == {True}


def test_channel_len_through_alias(go_types_helper):
    # `len(ch2)` resolves through the alias to the root queue —
    # dep-free on a local channel.
    result = named(
        *unit(
            go_types_helper,
            "func F(x int64) int64 {\n"
            "\tch := make(chan int64)\n"
            "\tch2 := ch\n"
            "\tch2 <- x\n"
            "\treturn int64(len(ch2))\n}\n",
        )
    )
    assert result.available
    assert result.return_dependencies == frozenset()


def test_channel_boundaries_stay_closed(go_types_helper):
    # A send through a selector (`p.C <- x`) admits under the same
    # external model a `chan` parameter or package var uses. A
    # select is modelled like an if/else chain whose guards are comm
    # ops: the receive's name takes the queue's deps and every
    # alternative joins by union. `make([]T)` now binds a scalar
    # container — `_ = s` folds nothing.
    slice_make = named(
        *unit(
            go_types_helper,
            "func F(x int64) int64 {\n"
            "\ts := make([]int64, 2)\n\t_ = s\n\treturn x\n}\n",
        )
    )
    assert slice_make.available
    select_case = named(
        *unit(
            go_types_helper,
            "func F(x int64) int64 {\n"
            "\tch := make(chan int64)\n\tch <- x\n"
            "\tselect {\n\tcase v := <-ch:\n\t\treturn v\n"
            "\tdefault:\n\t\treturn 0\n\t}\n}\n",
        )
    )
    assert select_case.available
    assert select_case.return_dependencies == frozenset({0})


def test_channel_non_scalar_element_stays_closed(go_types_helper):
    # `chan chan T` would let a channel VALUE travel through a queue
    # (`ch2, _ = <-q`) and alias it under a second dep set — the
    # under-approx the make-only bind gate exists to prevent. A
    # `chan *T`/`chan func()` element escapes the dep model the same
    # way, so channel bindings admit scalar elements only.
    for src in (
        "func F(x int64) int64 {\n"
        "\tq := make(chan chan int64)\n\t_ = q\n\treturn x\n}\n",
        "func F(x int64) int64 {\n"
        "\tvar q chan chan int64\n\t_ = q\n\treturn x\n}\n",
        "func F(x int64) int64 {\n"
        "\tq := make(chan *int64)\n\t_ = q\n\treturn x\n}\n",
        "func F(x int64) int64 {\n"
        "\tq := make(chan func() int64)\n\t_ = q\n\treturn x\n}\n",
        "func F(x int64) int64 {\n"
        "\tvar q chan func()\n\t_ = q\n\treturn x\n}\n",
    ):
        result = named(*unit(go_types_helper, src))
        assert not result.available


def test_channel_range_body_send_rejoins_element(go_types_helper):
    # `for v := range ch { ch <- y; *p = v }` — sends inside the
    # body widen the queue every pass; the element name must re-join
    # that grown set or `*p = v` stores the entry-time deps only.
    result = named(
        *unit(
            go_types_helper,
            "func F(x, y int64, p *int64) int64 {\n"
            "\tch := make(chan int64)\n\tch <- x\n"
            "\tfor v := range ch {\n\t\tch <- y\n\t\t*p = v\n\t}\n"
            "\treturn *p\n}\n",
        )
    )
    assert result.available
    assert result.return_dependencies == frozenset({0, 1, 2})


def test_channel_tuple_receive_reseats_external(go_types_helper):
    # `ch2, _ = <-Q` — a tuple-of-different-width assignment binds a
    # channel received out of an external `chan chan` queue: the name
    # detaches into the external model like `ch2 := <-Q`, so a later
    # send broadcasts and the receive reads it back through
    # `indirect_writes`. `Q` lives at package scope because a local
    # `chan chan int64` cannot be built at all.
    files = {
        "a.go": "package p\n"
        "var Q chan chan int64\n"
        "func F(x int64) int64 {\n"
        "\tch2 := make(chan int64)\n"
        "\tch2, _ = <-Q\n\tch2 <- x\n\treturn <-ch2\n}\n"
    }
    snapshot = _snapshot_for(go_types_helper, files)
    result = named_package(
        files, snapshot, ip.summarize_go_package(files, snapshot), "F"
    )
    assert result.available
    assert result.return_dependencies == frozenset({0})
    assert result.effects == "unknown"


def test_chan_chan_parameter_send_recv_chain(go_types_helper):
    # `cc chan chan int64` — the outer queue is caller-shared state:
    # `cc <- ch` records an imported effect and promotes the sent
    # channel external, so `c := <-cc` binds an external name whose
    # own receive observes the value sent through the chain.
    files = {
        "a.go": "package p\n"
        "func F(cc chan chan int64, x int64) int64 {\n"
        "\tch := make(chan int64, 1)\n"
        "\tch <- x\n"
        "\tcc <- ch\n"
        "\tc := <-cc\n"
        "\treturn <-c\n}\n"
    }
    snapshot = _snapshot_for(go_types_helper, files)
    result = named_package(
        files, snapshot, ip.summarize_go_package(files, snapshot), "F"
    )
    assert result.available
    assert result.return_dependencies == frozenset({0, 1})
    assert result.effects == "unknown"


def test_chan_chan_parameter_close_admitted(go_types_helper):
    # `close(cc)` on a `chan chan` parameter mutates caller-shared
    # queue state — an imported effect like `close` on a scalar
    # `chan` parameter.
    files = {
        "a.go": "package p\n"
        "func F(cc chan chan int64) int64 {\n"
        "\tclose(cc)\n"
        "\treturn 0\n}\n"
    }
    snapshot = _snapshot_for(go_types_helper, files)
    result = named_package(
        files, snapshot, ip.summarize_go_package(files, snapshot), "F"
    )
    assert result.available
    assert result.effects == "unknown"


