def test_local_chan_chan_share_group(
    go_types_helper, src, expected, effects
):
    result = named(*unit(go_types_helper, src))
    assert result.available, src
    assert result.return_dependencies == expected, src
    assert result.effects == effects, src
    if effects == "unknown":
        assert any(call.imported for call in result.calls), src


def test_local_chan_chan_group_keeps_imported_member_external(
    go_types_helper,
):
    files = {
        "a.go": "package p\nimport \"lib\"\n"
        "func F(x int64) int64 {\n"
        "\tcc := make(chan chan int64, 1)\n"
        "\tcc <- lib.GC\n"
        "\td := <-cc\n"
        "\td <- x\n"
        "\treturn <-lib.GC\n}\n"
    }
    lib = {"lib": {"g.go": "package lib\nvar GC chan int64\n"}}
    snapshot = load_go_package_snapshot(
        package_report_imports(go_types_helper, files, lib),
        files,
        target_arch="amd64",
    )
    result = named_package(
        files, snapshot, ip.summarize_go_package(files, snapshot), "F"
    )
    assert result.available
    assert result.return_dependencies == frozenset({0})
    assert result.effects == "unknown"
    assert any(call.imported for call in result.calls)


@pytest.mark.parametrize(
    "case, src, expected, effects",
    [
        (
            "multi-value var declaration keeps a callee result external",
            "func G(p int64) (int64, chan chan int64) {\n"
            "\treturn p, make(chan chan int64)\n"
            "}\n"
            "func F(p int64) int64 {\n"
            "\tvar n, cc = G(p)\n"
            "\t_ = cc\n"
            "\treturn n\n"
            "}\n",
            frozenset({0}),
            "none_in_supported_fragment",
        ),
        (
            "parallel chan chan assignment resolves pre-state groups",
            "func F(x int64) int64 {\n"
            "\tc := make(chan int64, 1)\n"
            "\ta := make(chan chan int64, 1)\n"
            "\tb := make(chan chan int64, 1)\n"
            "\ta <- c\n"
            "\ta, b = b, a\n"
            "\td := <-b\n"
            "\td <- x\n"
            "\treturn <-c\n"
            "}\n",
            frozenset({0}),
            "none_in_supported_fragment",
        ),
        (
            "aliases retain pre-receive queue contents",
            "func F(x int64) int64 {\n"
            "\tc := make(chan int64, 1)\n"
            "\tcc := make(chan chan int64, 1)\n"
            "\te := c\n"
            "\tc <- x\n"
            "\tc = <-cc\n"
            "\treturn <-e\n"
            "}\n",
            frozenset({0}),
            "none_in_supported_fragment",
        ),
        (
            "select receive detaches the previous channel alias",
            "func F(x int64) int64 {\n"
            "\tc := make(chan int64, 1)\n"
            "\ta := make(chan int64, 1)\n"
            "\tcc := make(chan chan int64, 1)\n"
            "\tcc <- c\n"
            "\td := a\n"
            "\tselect {\n"
            "\tcase d = <-cc:\n"
            "\t\td <- x\n"
            "\t}\n"
            "\treturn <-c\n"
            "}\n",
            frozenset({0}),
            "none_in_supported_fragment",
        ),
        (
            "select with default preserves the skipped receive alias",
            "func F(x int64) int64 {\n"
            "\tc := make(chan int64, 1)\n"
            "\tc <- 7\n"
            "\te := make(chan int64, 1)\n"
            "\tcc := make(chan chan int64, 1)\n"
            "\tcc <- e\n"
            "\td := c\n"
            "\tselect {\n"
            "\tcase d = <-cc:\n"
            "\tdefault:\n"
            "\t}\n"
            "\td <- x\n"
            "\treturn <-c\n"
            "}\n",
            frozenset({0}),
            "none_in_supported_fragment",
        ),
        (
            "if receive reassignment preserves the skipped alias",
            "func F(x int64, b bool) int64 {\n"
            "\tc := make(chan int64, 1)\n"
            "\te := make(chan int64, 1)\n"
            "\tcc := make(chan chan int64, 1)\n"
            "\tcc <- e\n"
            "\td := c\n"
            "\tif b {\n"
            "\t\td = <-cc\n"
            "\t}\n"
            "\td <- x\n"
            "\treturn <-c\n"
            "}\n",
            frozenset({0}),
            "none_in_supported_fragment",
        ),
        (
            "comma-ok receive reassignment preserves the skipped alias",
            "func F(x int64, b bool) int64 {\n"
            "\tc := make(chan int64, 1)\n"
            "\te := make(chan int64, 1)\n"
            "\tcc := make(chan chan int64, 1)\n"
            "\tcc <- e\n"
            "\td := c\n"
            "\tif b {\n"
            "\t\td, _ = <-cc\n"
            "\t}\n"
            "\td <- x\n"
            "\treturn <-c\n"
            "}\n",
            frozenset({0}),
            "none_in_supported_fragment",
        ),
        (
            "closed empty chan chan range preserves the old alias",
            "func F(x int64) int64 {\n"
            "\tc := make(chan int64, 1)\n"
            "\tcc := make(chan chan int64)\n"
            "\tclose(cc)\n"
            "\td := c\n"
            "\tfor d = range cc {\n"
            "\t}\n"
            "\td <- x\n"
            "\treturn <-c\n"
            "}\n",
            frozenset({0}),
            "none_in_supported_fragment",
        ),
        (
            "single-case select receive drops the old alias",
            "func F(x int64) int64 {\n"
            "\tc := make(chan int64, 1)\n"
            "\tc <- 7\n"
            "\te := make(chan int64, 1)\n"
            "\tcc := make(chan chan int64, 1)\n"
            "\tcc <- e\n"
            "\td := c\n"
            "\tselect {\n"
            "\tcase d = <-cc:\n"
            "\t}\n"
            "\td <- x\n"
            "\treturn <-c\n"
            "}\n",
            frozenset(),
            "none_in_supported_fragment",
        ),
        (
            "unconditional receive reassignment drops the old alias",
            "func F(x int64) int64 {\n"
            "\tc := make(chan int64, 1)\n"
            "\tc <- 7\n"
            "\te := make(chan int64, 1)\n"
            "\tcc := make(chan chan int64, 1)\n"
            "\tcc <- e\n"
            "\td := c\n"
            "\td = <-cc\n"
            "\td <- x\n"
            "\treturn <-c\n"
            "}\n",
            frozenset(),
            "none_in_supported_fragment",
        ),
        (
            "multi-value var receive joins the local chan chan group",
            "func F(x int64) int64 {\n"
            "\tc := make(chan int64, 1)\n"
            "\tcc := make(chan chan int64, 1)\n"
            "\tcc <- c\n"
            "\tvar d, ok = <-cc\n"
            "\t_ = ok\n"
            "\td <- x\n"
            "\treturn <-c\n"
            "}\n",
            frozenset({0}),
            "none_in_supported_fragment",
        ),
        (
            "received channel group joins the destination queue",
            "func F(x int64) int64 {\n"
            "\tc := make(chan int64, 1)\n"
            "\tcc := make(chan chan int64, 1)\n"
            "\tcc2 := make(chan chan int64, 1)\n"
            "\tcc <- c\n"
            "\tcc2 <- <-cc\n"
            "\td := <-cc2\n"
            "\td <- x\n"
            "\treturn <-c\n"
            "}\n",
            frozenset({0}),
            "none_in_supported_fragment",
        ),
        (
            "scalar channel receive can be sent to another queue",
            # Sending a received channel value is supported.
            "func F(x int64) int64 {\n"
            "\tin := make(chan int64, 1)\n"
            "\tout := make(chan int64, 1)\n"
            "\tin <- x\n"
            "\tout <- <-in\n"
            "\treturn <-out\n"
            "}\n",
            frozenset({0}),
            "none_in_supported_fragment",
        ),
    ],
)
def test_local_chan_chan_review_regressions(
    go_types_helper, case, src, expected, effects
):
    result = named(*unit(go_types_helper, src))
    assert result.available, case
    assert result.return_dependencies == expected, case
    assert result.effects == effects, case


@pytest.mark.parametrize(
    "queue_source",
    ("local", "local-with-external-member", "parameter", "promoted"),
)
def test_received_channel_operation_targets_match_temporary(
    go_types_helper, queue_source
):
    forms = {
        "send_target": (
            "(<-q) <- x\n\treturn <-c\n",
            "tmp := <-q\n\ttmp <- x\n\treturn <-c\n",
        ),
        "return_receive": (
            "return <-(<-q)\n",
            "tmp := <-q\n\treturn <-tmp\n",
        ),
        "short_declaration": (
            "v := <-(<-q)\n\treturn v\n",
            "tmp := <-q\n\tv := <-tmp\n\treturn v\n",
        ),
        "assignment": (
            "var v int64\n\tv = <-(<-q)\n\treturn v\n",
            "tmp := <-q\n\tvar v int64\n\tv = <-tmp\n\treturn v\n",
        ),
        "var_initialization": (
            "var v int64 = <-(<-q)\n\treturn v\n",
            "tmp := <-q\n\tvar v int64 = <-tmp\n\treturn v\n",
        ),
        "comma_ok": (
            "v, ok := <-(<-q)\n\tif ok {\n\t\treturn v\n\t}\n\treturn 0\n",
            "tmp := <-q\n\tv, ok := <-tmp\n\tif ok {\n\t\treturn v\n\t}\n\treturn 0\n",
        ),
        "bare_receive": (
            "<-(<-q)\n\treturn <-c\n",
            "tmp := <-q\n\t<-tmp\n\treturn <-c\n",
        ),
        "send_value": (
            "dst := make(chan int64, 1)\n\tdst <- <-(<-q)\n"
            "\treturn <-dst\n",
            "tmp := <-q\n\tdst := make(chan int64, 1)\n"
            "\tdst <- <-tmp\n\treturn <-dst\n",
        ),
        "close": (
            "close(<-q)\n\treturn <-c\n",
            "tmp := <-q\n\tclose(tmp)\n\treturn <-c\n",
        ),
        "len": (
            "_ = len(<-q)\n\treturn <-c\n",
            "tmp := <-q\n\t_ = len(tmp)\n\treturn <-c\n",
        ),
        "cap": (
            "_ = cap(<-q)\n\treturn <-c\n",
            "tmp := <-q\n\t_ = cap(tmp)\n\treturn <-c\n",
        ),
        "range": (
            "for v := range <-q {\n\t\treturn v\n\t}\n\treturn <-c\n",
            "tmp := <-q\n\tfor v := range tmp {\n\t\treturn v\n"
            "\t}\n\treturn <-c\n",
        ),
        "select_send": (
            "select {\n\tcase (<-q) <- x:\n\t\treturn <-c\n"
            "\tdefault:\n\t\treturn <-c\n\t}\n",
            "tmp := <-q\n\tselect {\n\tcase tmp <- x:\n"
            "\t\treturn <-c\n\tdefault:\n\t\treturn <-c\n\t}\n",
        ),
        "select_receive": (
            "select {\n\tcase v := <-(<-q):\n\t\treturn v\n"
            "\tdefault:\n\t\treturn <-c\n\t}\n",
            "tmp := <-q\n\tselect {\n\tcase v := <-tmp:\n"
            "\t\treturn v\n\tdefault:\n\t\treturn <-c\n\t}\n",
        ),
        "select_comma_ok": (
            "select {\n\tcase v, ok := <-(<-q):\n\t\tif ok {\n"
            "\t\t\treturn v\n\t\t}\n\t\treturn 0\n"
            "\tdefault:\n\t\treturn <-c\n\t}\n",
            "tmp := <-q\n\tselect {\n\tcase v, ok := <-tmp:\n"
            "\t\tif ok {\n\t\t\treturn v\n\t\t}\n\t\treturn 0\n"
            "\tdefault:\n\t\treturn <-c\n\t}\n",
        ),
        "select_bare_receive": (
            "select {\n\tcase <-(<-q):\n\t\treturn <-c\n"
            "\tdefault:\n\t\treturn <-c\n\t}\n",
            "tmp := <-q\n\tselect {\n\tcase <-tmp:\n"
            "\t\treturn <-c\n\tdefault:\n\t\treturn <-c\n\t}\n",
        ),
    }
    prelude = "package p\n"
    if queue_source == "promoted":
        prelude += (
            "func Promote(cc chan chan int64, x int64) {\n"
            "\td := <-cc\n"
            "\td <- x\n"
            "}\n"
        )
    functions = []
    for form, (nested, temporary) in forms.items():
        for variant, body in (("nested", nested), ("temporary", temporary)):
            setup = (
                "\tc := make(chan int64, 1)\n"
                "\tc <- x\n"
            )
            if queue_source == "parameter":
                setup += "\tp <- c\n"
                queue_name = "p"
            else:
                setup += (
                    "\tcc := make(chan chan int64, 2)\n"
                    "\tcc <- c\n"
                )
                if queue_source == "local-with-external-member":
                    setup += "\tcc <- ec\n"
                if queue_source == "promoted":
                    setup += "\tPromote(cc, x)\n"
                setup += "\tq := cc\n"
                queue_name = "q"
            functions.append(
                f"func F_{form}_{variant}("
                "x int64, ec chan int64, p chan chan int64"
                ") int64 {\n"
                + setup
                + "\t"
                + body.replace("q", queue_name)
                .replace("\n", "\n\t")
                .rstrip()
                + "\n}\n"
            )
    files = {"a.go": prelude + "".join(functions)}
    _, snapshot, summaries = package_unit(go_types_helper, files)

    def transfer_shape(summary):
        return sorted(
            {
                (
                    transfer.imported,
                    tuple(
                        tuple(sorted(argument))
                        for argument in transfer.arguments
                    ),
                    tuple(sorted(transfer.result)),
                )
                for transfer in summary.calls
            }
        )

    for form in forms:
        nested = named_package(
            files, snapshot, summaries, f"F_{form}_nested"
        )
        temporary = named_package(
            files, snapshot, summaries, f"F_{form}_temporary"
        )
        assert nested.available, (queue_source, form, nested.gaps)
        assert temporary.available, (queue_source, form, temporary.gaps)
        assert nested.return_dependencies == temporary.return_dependencies, (
            queue_source,
            form,
        )
        assert nested.effects == temporary.effects, (queue_source, form)
        if queue_source == "local":
            assert nested.effects == "none_in_supported_fragment", form
        assert transfer_shape(nested) == transfer_shape(temporary), (
            queue_source,
            form,
        )


def test_received_channel_operation_target_expected_dependencies(
    go_types_helper,
):
    files = {
        "a.go": "package p\n"
        "func Local(x int64) int64 {\n"
        "\tc := make(chan int64, 1)\n"
        "\tcc := make(chan chan int64, 1)\n"
        "\tcc <- c\n"
        "\t(<-cc) <- x\n"
        "\treturn <-c\n"
        "}\n"
        "func F(cc chan chan int64) int64 {\n"
        "\treturn <-(<-(cc))\n"
        "}\n"
        "func FTemp(cc chan chan int64) int64 {\n"
        "\td := <-(cc)\n"
        "\treturn <-d\n"
        "}\n"
    }
    _, snapshot, summaries = package_unit(go_types_helper, files)
    local = named_package(files, snapshot, summaries, "Local")
    assert local.available
    assert local.return_dependencies == frozenset({0})
    assert local.effects == "none_in_supported_fragment"
    for name in ("F", "FTemp"):
        result = named_package(files, snapshot, summaries, name)
        assert result.available
        assert result.return_dependencies == frozenset({0})
        assert result.effects == "unknown"


def test_external_chan_chan_queue_aliases_match_direct(
    go_types_helper,
):
    source_specs = {
        "parameter": ("p chan chan int64, x int64", "", "p", "p"),
        "package": ("x int64", "", "GCC", "GCC"),
        "imported_global": (
            "x int64",
            "",
            "lib.GCC",
            "lib.GCC",
        ),
        "local_result": (
            "x int64",
            "cc := G()",
            "cc",
            "cc",
        ),
        "imported_result": (
            "x int64",
            "cc := lib.G()",
            "cc",
            "cc",
        ),
    }
    alias_forms = {
        "short": lambda operand: f"q := {operand}",
        "var_inferred": lambda operand: f"var q = {operand}",
        "var_typed": lambda operand: (
            f"var q chan chan int64 = {operand}"
        ),
        "assignment": lambda operand: (
            f"var q chan chan int64\nq = {operand}"
        ),
        "short_reassignment": lambda operand: (
            f"q := {operand}\nq = {operand}"
        ),
    }
    operations = {
        "chain": "d := <-{Q}\nd <- x\nreturn <-d",
        "nested_receive": "return <-(<-{Q})",
        "send_target": "(<-{Q}) <- x\nreturn x",
        "close_received": "close(<-{Q})\nreturn x",
        "length": "_ = len({Q})\nreturn x",
        "capacity": "_ = cap({Q})\nreturn x",
        "range": "for d := range {Q} {{\n\treturn <-d\n}}\nreturn x",
        "select_receive": (
            "select {{\n\tcase d := <-{Q}:\n\t\treturn <-d\n"
            "\tdefault:\n\t\treturn x\n}}"
        ),
        "select_send": (
            "c := make(chan int64, 1)\n"
            "select {{\n\tcase {Q} <- c:\n\t\treturn x\n"
            "\tdefault:\n\t\treturn x\n}}"
        ),
        "direct_local_call": "return G2({Q}, x)",
    }

    def add_function(name, parameters, setup, body):
        lines = [line for line in setup.splitlines() if line]
        lines.extend(body.splitlines())
        return (
            f"func {name}({parameters}) int64 {{\n"
            + "\n".join(f"\t{line}" for line in lines)
            + "\n}\n"
        )

    def transfer_shape(summary):
        return sorted(
            (
                transfer.imported,
                tuple(
                    tuple(sorted(argument))
                    for argument in transfer.arguments
                ),
                tuple(sorted(transfer.result)),
            )
            for transfer in summary.calls
        )

    for source, (parameters, setup, direct, alias_operand) in (
        source_specs.items()
    ):
        declarations = [
            "var GCC chan chan int64",
            "func G() chan chan int64 { return GCC }",
            "func G2(cc chan chan int64, x int64) int64 {\n"
            "\td := <-cc\n\td <- x\n\treturn <-d\n}",
        ]
        body = operations["chain"].format(Q=direct)
        for alias_name, alias_builder in alias_forms.items():
            if alias_name == "short_reassignment" and source != "parameter":
                continue
            declarations.append(
                add_function(
                    f"F_{source}_{alias_name}_direct",
                    parameters,
                    setup,
                    body,
                )
            )
            declarations.append(
                add_function(
                    f"F_{source}_{alias_name}_alias",
                    parameters,
                    setup + "\n" + alias_builder(alias_operand),
                    operations["chain"].format(Q="q"),
                )
            )
        for operation, template in operations.items():
            if operation == "chain":
                continue
            declarations.append(
                add_function(
                    f"F_{source}_{operation}_direct",
                    parameters,
                    setup,
                    template.format(Q=direct),
                )
            )
            declarations.append(
                add_function(
                    f"F_{source}_{operation}_alias",
                    parameters,
                    setup + "\n" + f"q := {alias_operand}",
                    template.format(Q="q"),
                )
            )
        package_import = (
            'import "lib"\n'
            if source in ("imported_global", "imported_result")
            else ""
        )
        files = {
            "a.go": "package p\n" + package_import
            + "\n".join(declarations),
        }
        imports = {
            "lib": {
                "channels.go": (
                    "package lib\n"
                    "var GCC chan chan int64\n"
                    "func G() chan chan int64 { return GCC }\n"
                )
            }
        }
        snapshot = load_go_package_snapshot(
            package_report_imports(go_types_helper, files, imports),
            files,
            target_arch="amd64",
        )
        summaries = ip.summarize_go_package(files, snapshot)
        for alias_name in alias_forms:
            if alias_name == "short_reassignment" and source != "parameter":
                continue
            direct_summary = named_package(
                files,
                snapshot,
                summaries,
                f"F_{source}_{alias_name}_direct",
            )
            alias_summary = named_package(
                files,
                snapshot,
                summaries,
                f"F_{source}_{alias_name}_alias",
            )
            assert direct_summary.available
            assert alias_summary.available, (source, alias_name, alias_summary.gaps)
            assert (
                alias_summary.return_dependencies
                == direct_summary.return_dependencies
            ), (source, alias_name)
            assert alias_summary.effects == direct_summary.effects, (
                source,
                alias_name,
            )
            assert transfer_shape(alias_summary) == transfer_shape(
                direct_summary
            ), (source, alias_name)
            for operation in operations:
                if operation == "chain":
                    continue
                direct_summary = named_package(
                    files,
                    snapshot,
                    summaries,
                    f"F_{source}_{operation}_direct",
                )
                alias_summary = named_package(
                    files,
                    snapshot,
                    summaries,
                    f"F_{source}_{operation}_alias",
                )
                assert direct_summary.available, (
                    source,
                    operation,
                    direct_summary.gaps,
                )
                assert alias_summary.available, (
                    source,
                    operation,
                    alias_summary.gaps,
                )
                assert (
                    alias_summary.return_dependencies
                    == direct_summary.return_dependencies
                ), (source, operation)
                assert alias_summary.effects == direct_summary.effects, (
                    source,
                    operation,
                )
                assert transfer_shape(alias_summary) == transfer_shape(
                    direct_summary
                ), (source, operation)


def test_external_chan_chan_alias_reassignment_preserves_origins(
    go_types_helper,
):
    source, snapshot, summaries = unit(
        go_types_helper,
        "func F(p chan chan int64) int64 {\n"
        "\tq := p\n\treturn <-(<-q)\n}\n"
        "func Direct(p chan chan int64) int64 {\n"
        "\treturn <-(<-p)\n}\n"
        "func Conditional(p1, p2 chan chan int64, b bool) int64 {\n"
        "\tq := p1\n\tif b { q = p2 }\n\treturn <-(<-q)\n}\n"
        "func Strong(p1, p2 chan chan int64) int64 {\n"
        "\tq := p1\n\tq = p2\n\treturn <-(<-q)\n}\n"
        "func StrongDirect(p1, p2 chan chan int64) int64 {\n"
        "\treturn <-(<-p2)\n"
        "}\n",
    )
    alias = named(source, snapshot, summaries, "F")
    direct = named(source, snapshot, summaries, "Direct")
    conditional = named(source, snapshot, summaries, "Conditional")
    strong = named(source, snapshot, summaries, "Strong")
    strong_direct = named(source, snapshot, summaries, "StrongDirect")
    assert alias.available and direct.available
    assert alias.return_dependencies == direct.return_dependencies == {0}
    assert conditional.available
    assert conditional.return_dependencies >= {0, 1}
    assert strong.available and strong_direct.available
    assert strong.return_dependencies == strong_direct.return_dependencies == {
        1
    }


def test_local_chan_chan_reseat_to_external_queue_promotes_members(
    go_types_helper,
):
    files = {
        "a.go": "package p\nimport \"lib\"\n"
        "var GCC chan chan int64\n"
        "func G() chan chan int64 { return GCC }\n"
        "func FromParam(p chan chan int64, x int64) int64 {\n"
        "\tcc := make(chan chan int64, 1)\n"
        "\tc := make(chan int64, 1)\n"
        "\tcc <- c\n\tcc = p\n\td := <-cc\nd <- x\nreturn <-c\n}\n"
        "func Conditional(p chan chan int64, x int64, b bool) int64 {\n"
        "\tcc := make(chan chan int64, 1)\n"
        "\tc := make(chan int64, 1)\n"
        "\tcc <- c\n\tif b { cc = p }\n"
        "\td := <-cc\nd <- x\nreturn <-c\n}\n"
        "func FromCall(x int64) int64 {\n"
        "\tcc := make(chan chan int64, 1)\n"
        "\tc := make(chan int64, 1)\n"
        "\tcc <- c\n\tcc = G()\nd := <-cc\nd <- x\nreturn <-c\n}\n"
        "func FromImport(x int64) int64 {\n"
        "\tcc := make(chan chan int64, 1)\n"
        "\tc := make(chan int64, 1)\n"
        "\tcc <- c\n\tcc = lib.G()\nd := <-cc\nd <- x\nreturn <-c\n}\n"
        "func ConditionalCall(x int64, b bool) int64 {\n"
        "\tcc := make(chan chan int64, 1)\n"
        "\tc := make(chan int64, 1)\n"
        "\tcc <- c\n\tif b { cc = G() }\n"
        "\td := <-cc\nd <- x\nreturn <-c\n}\n"
        "func LocalOnly(x int64) int64 {\n"
        "\tcc := make(chan chan int64, 1)\n"
        "\tc := make(chan int64, 1)\n"
        "\tcc <- c\nd := <-cc\nd <- x\nreturn <-c\n}\n",
    }
    imports = {
        "lib": {
            "channels.go": (
                "package lib\n"
                "var GCC chan chan int64\n"
                "func G() chan chan int64 { return GCC }\n"
            )
        }
    }
    snapshot = load_go_package_snapshot(
        package_report_imports(go_types_helper, files, imports),
        files,
        target_arch="amd64",
    )
    summaries = ip.summarize_go_package(files, snapshot)
    for name in (
        "FromParam",
        "Conditional",
        "FromCall",
        "FromImport",
        "ConditionalCall",
    ):
        result = named_package(files, snapshot, summaries, name)
        assert result.available, (name, result.gaps)
        assert result.effects == "unknown", name
        assert result.return_dependencies >= (
            {0, 1} if name in {"FromParam", "Conditional"} else {0}
        ), name
    local = named_package(files, snapshot, summaries, "LocalOnly")
    assert local.available
    assert local.return_dependencies == {0}
    assert local.effects == "none_in_supported_fragment"


def test_direct_chan_chan_call_result_operands_match_temporary(
    go_types_helper,
):
    operations = {
        "nested_receive": (
            "return <-(<-{G})",
            "return <-(<-cc)",
        ),
        "send_target": (
            "(<-{G}) <- x\nreturn x",
            "(<-cc) <- x\nreturn x",
        ),
        "send_queue_target": (
            "c := make(chan int64, 1)\n"
            "{G} <- c\n"
            "d := <-{Queue}\nd <- x\nreturn <-c",
            "c := make(chan int64, 1)\n"
            "cc <- c\n"
            "d := <-{Queue}\nd <- x\nreturn <-c",
        ),
        "select_send_queue_target": (
            "c := make(chan int64, 1)\n"
            "select {{\n\tcase {G} <- c:\n"
            "\tdefault:\n}}\n"
            "d := <-{Queue}\nd <- x\nreturn <-c",
            "c := make(chan int64, 1)\n"
            "select {{\n\tcase cc <- c:\n"
            "\tdefault:\n}}\n"
            "d := <-{Queue}\nd <- x\nreturn <-c",
        ),
        "send_received_value": (
            "c := make(chan int64, 1)\n"
            "{Queue} <- c\n"
            "dst := make(chan chan int64, 1)\n"
            "dst <- <-{G}\nd := <-dst\nd <- x\nreturn <-c",
            "c := make(chan int64, 1)\n"
            "{Queue} <- c\n"
            "dst := make(chan chan int64, 1)\n"
            "t := <-cc\ndst <- t\nd := <-dst\nd <- x\nreturn <-c",
        ),
        "receive_binding": (
            "d := <-{G}\nd <- x\nreturn <-d",
            "d := <-cc\nd <- x\nreturn <-d",
        ),
        "receive_comma_ok": (
            "d, ok := <-{G}\nif ok {{ d <- x }}\nreturn <-d",
            "d, ok := <-cc\nif ok {{ d <- x }}\nreturn <-d",
        ),
        "receive_assignment": (
            "d := make(chan int64, 1)\nd = <-{G}\n"
            "d <- x\nreturn <-d",
            "d := make(chan int64, 1)\nd = <-cc\n"
            "d <- x\nreturn <-d",
        ),
        "select_receive_binding": (
            "select {{\n\tcase d := <-{G}:\n"
            "\t\td <- x\n\t\treturn <-d\n"
            "\tdefault:\n\t\treturn x\n}}",
            "select {{\n\tcase d := <-cc:\n"
            "\t\td <- x\n\t\treturn <-d\n"
            "\tdefault:\n\t\treturn x\n}}",
        ),
        "close": (
            "close(<-{G})\nreturn x",
            "close(<-cc)\nreturn x",
        ),
        "length": (
            "_ = len({G})\nreturn x",
            "_ = len(cc)\nreturn x",
        ),
        "capacity": (
            "_ = cap({G})\nreturn x",
            "_ = cap(cc)\nreturn x",
        ),
        "received_length": (
            "_ = len(<-{G})\nreturn x",
            "_ = len(<-cc)\nreturn x",
        ),
        "received_capacity": (
            "_ = cap(<-{G})\nreturn x",
            "_ = cap(<-cc)\nreturn x",
        ),
        "range": (
            "for d := range <-{G} {{\n\treturn d\n}}\nreturn x",
            "for d := range <-cc {{\n\treturn d\n}}\nreturn x",
        ),
        "select_send": (
            "select {{\n\tcase (<-{G}) <- x:\n"
            "\t\treturn x\n\tdefault:\n\t\treturn x\n}}",
            "select {{\n\tcase (<-cc) <- x:\n"
            "\t\treturn x\n\tdefault:\n\t\treturn x\n}}",
        ),
        "select_receive": (
            "select {{\n\tcase v := <-(<-{G}):\n"
            "\t\treturn v\n\tdefault:\n\t\treturn x\n}}",
            "select {{\n\tcase v := <-(<-cc):\n"
            "\t\treturn v\n\tdefault:\n\t\treturn x\n}}",
        ),
        "select_receive_ok": (
            "select {{\n\tcase v, ok := <-(<-{G}):\n"
            "\t\tif ok {{ return v }}\n\t\treturn x\n"
            "\tdefault:\n\t\treturn x\n}}",
            "select {{\n\tcase v, ok := <-(<-cc):\n"
            "\t\tif ok {{ return v }}\n\t\treturn x\n"
            "\tdefault:\n\t\treturn x\n}}",
        ),
        "select_receive_bare": (
            "select {{\n\tcase <-(<-{G}):\n"
            "\t\treturn x\n\tdefault:\n\t\treturn x\n}}",
            "select {{\n\tcase <-(<-cc):\n"
            "\t\treturn x\n\tdefault:\n\t\treturn x\n}}",
        ),
    }
    declarations = [
        "var GCC chan chan int64",
        "func G() chan chan int64 { return GCC }",
    ]
    for source in ("local", "imported"):
        call = "G()" if source == "local" else "lib.G()"
        queue = "GCC" if source == "local" else "lib.GCC"
        for operation, (direct_body, temporary_body) in operations.items():
            declarations.append(
                f"func F_{source}_{operation}_direct(x int64) int64 {{\n"
                + "\n".join(
                    f"\t{line}"
                    for line in direct_body.format(
                        G=call, Queue=queue
                    ).splitlines()
                )
                + "\n}\n"
            )
            declarations.append(
                f"func F_{source}_{operation}_temporary(x int64) int64 {{\n"
                f"\tcc := {call}\n"
                + "\n".join(
                    f"\t{line}"
                    for line in temporary_body.format(
                        G=call, Queue=queue
                    ).splitlines()
                )
                + "\n}\n"
            )
    files = {
        "a.go": "package p\nimport \"lib\"\n" + "\n".join(declarations),
    }
    imports = {
        "lib": {
            "channels.go": (
                "package lib\n"
                "var GCC chan chan int64\n"
                "func G() chan chan int64 { return GCC }\n"
            )
        }
    }
    snapshot = load_go_package_snapshot(
        package_report_imports(go_types_helper, files, imports),
        files,
        target_arch="amd64",
    )
    summaries = ip.summarize_go_package(files, snapshot)

    def transfer_shape(summary):
        return sorted(
            (
                transfer.imported,
                tuple(
                    tuple(sorted(argument))
                    for argument in transfer.arguments
                ),
                tuple(sorted(transfer.result)),
            )
            for transfer in summary.calls
        )

    differences = []
    for source in ("local", "imported"):
        for operation in operations:
            direct = named_package(
                files,
                snapshot,
                summaries,
                f"F_{source}_{operation}_direct",
            )
            temporary = named_package(
                files,
                snapshot,
                summaries,
                f"F_{source}_{operation}_temporary",
            )
            if not direct.available or not temporary.available:
                differences.append(
                    (
                        source,
                        operation,
                        "availability",
                        direct.available,
                        direct.gaps,
                        temporary.available,
                        temporary.gaps,
                    )
                )
            else:
                for label, direct_value, temporary_value in (
                    (
                        "return_dependencies",
                        direct.return_dependencies,
                        temporary.return_dependencies,
                    ),
                    ("effects", direct.effects, temporary.effects),
                    (
                        "transfers",
                        transfer_shape(direct),
                        transfer_shape(temporary),
                    ),
                ):
                    if direct_value != temporary_value:
                        differences.append(
                            (
                                source,
                                operation,
                                label,
                                direct_value,
                                temporary_value,
                            )
                        )
    assert not differences, "\n".join(
        repr(difference) for difference in differences
    )
    for source in ("local", "imported"):
        for operation in (
            "send_queue_target",
            "select_send_queue_target",
            "send_received_value",
            "receive_binding",
            "receive_comma_ok",
            "receive_assignment",
            "select_receive_binding",
        ):
            result = named_package(
                files,
                snapshot,
                summaries,
                f"F_{source}_{operation}_direct",
            )
            assert result.return_dependencies == {0}, (
                source,
                operation,
                result.return_dependencies,
            )


def test_received_external_channel_value_joins_local_queue(
    go_types_helper,
):
    files = {
        "a.go": "package p\n"
        "func External(p chan chan int64, x int64) int64 {\n"
        "\tdst := make(chan chan int64, 1)\n"
        "\tdst <- <-p\nd := <-dst\nd <- x\nreturn <-d\n}\n"
        "func ExternalTemporary(p chan chan int64, x int64) int64 {\n"
        "\tdst := make(chan chan int64, 1)\n"
        "\tt := <-p\ndst <- t\nd := <-dst\nd <- x\nreturn <-d\n}\n"
        "func Local(x int64) int64 {\n"
        "\tsrc := make(chan chan int64, 1)\n"
        "\tdst := make(chan chan int64, 1)\n"
        "\tc := make(chan int64, 1)\n"
        "\tsrc <- c\ndst <- <-src\nd := <-dst\nd <- x\nreturn <-c\n}\n"
        "func LocalTemporary(x int64) int64 {\n"
        "\tsrc := make(chan chan int64, 1)\n"
        "\tdst := make(chan chan int64, 1)\n"
        "\tc := make(chan int64, 1)\n"
        "\tsrc <- c\nt := <-src\ndst <- t\nd := <-dst\nd <- x\n"
        "\treturn <-c\n}\n",
    }
    _, snapshot, summaries = package_unit(go_types_helper, files)
    for direct_name, temporary_name in (
        ("External", "ExternalTemporary"),
        ("Local", "LocalTemporary"),
    ):
        direct = named_package(files, snapshot, summaries, direct_name)
        temporary = named_package(
            files, snapshot, summaries, temporary_name
        )
        assert direct.available, (direct_name, direct.gaps)
        assert temporary.available, (temporary_name, temporary.gaps)
        assert direct.return_dependencies == temporary.return_dependencies
        assert direct.effects == temporary.effects
        assert sorted(
            (
                transfer.imported,
                tuple(
                    tuple(sorted(argument))
                    for argument in transfer.arguments
                ),
                tuple(sorted(transfer.result)),
            )
            for transfer in direct.calls
        ) == sorted(
            (
                transfer.imported,
                tuple(
                    tuple(sorted(argument))
                    for argument in transfer.arguments
                ),
                tuple(sorted(transfer.result)),
            )
            for transfer in temporary.calls
        )
    external = named_package(files, snapshot, summaries, "External")
    assert external.return_dependencies == {0, 1}
    local = named_package(files, snapshot, summaries, "Local")
    assert local.effects == "none_in_supported_fragment"


@pytest.mark.parametrize(
    "variant",
    [
        "direct",
        "alias",
        "multi-result",
        "named-result",
        "branch-return",
        "external-member",
        "member-enqueued-before-send",
        "member-enqueued-after-send",
        "unbuffered",
        "defer-after-return",
    ],
)
def test_local_chan_chan_return_escape_matches_inline(
    go_types_helper, variant
):
    capacity = "" if variant == "unbuffered" else ", 1"
    queue_setup = (
        f"cc := make(chan chan int64{capacity})\n"
        f"c := make(chan int64{capacity})\n"
    )
    if variant in {"direct", "unbuffered"}:
        maker = (
            "func G(x int64) chan chan int64 {\n"
            + queue_setup
            + "\tcc <- c\n"
            "\tc <- x\n"
            "\treturn cc\n}\n"
        )
        uses = (
            "func Direct(x int64) int64 { return <-(<-G(x)) }\n"
            "func Bound(x int64) int64 {\n"
            "\tcc := G(x)\n"
            "\td := <-cc\n"
            "\treturn <-d\n}\n"
        )
        inline = (
            "func Inline(x int64) int64 {\n"
            + queue_setup
            + "\tcc <- c\n"
            "\tc <- x\n"
            "\td := <-cc\n"
            "\treturn <-d\n}\n"
        )
        compare = ("Direct", "Bound")
        expected = frozenset({0})
    elif variant == "alias":
        maker = (
            "func G(x int64) chan chan int64 {\n"
            + queue_setup
            + "\tcc <- c\n"
            "\tc <- x\n"
            "\tq := cc\n"
            "\treturn q\n}\n"
        )
        uses = (
            "func Use(x int64) int64 {\n"
            "\tcc := G(x)\n"
            "\td := <-cc\n"
            "\treturn <-d\n}\n"
        )
        inline = (
            "func Inline(x int64) int64 {\n"
            + queue_setup
            + "\tcc <- c\n"
            "\tc <- x\n"
            "\td := <-cc\n"
            "\treturn <-d\n}\n"
        )
        compare = ("Use",)
        expected = frozenset({0})
    elif variant == "multi-result":
        maker = (
            "func G(x int64) (chan chan int64, bool) {\n"
            + queue_setup
            + "\tcc <- c\n"
            "\tc <- x\n"
            "\treturn cc, true\n}\n"
        )
        uses = (
            "func Use(x int64) int64 {\n"
            "\tcc, _ := G(x)\n"
            "\td := <-cc\n"
            "\treturn <-d\n}\n"
        )
        inline = (
            "func Inline(x int64) int64 {\n"
            + queue_setup
            + "\tcc <- c\n"
            "\tc <- x\n"
            "\td := <-cc\n"
            "\treturn <-d\n}\n"
        )
        compare = ("Use",)
        expected = frozenset({0})
    elif variant == "named-result":
        maker = (
            "func G(x int64) (r chan chan int64) {\n"
            + queue_setup
            + "\tcc <- c\n"
            "\tc <- x\n"
            "\tr = cc\n"
            "\treturn\n}\n"
        )
        uses = (
            "func Use(x int64) int64 {\n"
            "\tcc := G(x)\n"
            "\td := <-cc\n"
            "\treturn <-d\n}\n"
        )
        inline = (
            "func Inline(x int64) int64 {\n"
            + queue_setup
            + "\tcc <- c\n"
            "\tc <- x\n"
            "\td := <-cc\n"
            "\treturn <-d\n}\n"
        )
        compare = ("Use",)
        expected = frozenset({0})
    elif variant == "branch-return":
        maker = (
            "func G(x int64, b bool) chan chan int64 {\n"
            + queue_setup
            + "\tcc <- c\n"
            "\tc <- x\n"
            "\tif b { return cc }\n"
            "\treturn cc\n}\n"
        )
        uses = (
            "func Use(x int64, b bool) int64 {\n"
            "\tcc := G(x, b)\n"
            "\td := <-cc\n"
            "\treturn <-d\n}\n"
        )
        inline = (
            "func Inline(x int64, b bool) int64 {\n"
            + queue_setup
            + "\tcc <- c\n"
            "\tc <- x\n"
            "\td := <-cc\n"
            "\treturn <-d\n}\n"
        )
        compare = ("Use",)
        expected = frozenset({0})
    elif variant == "external-member":
        maker = (
            "func G(p chan int64, x int64) chan chan int64 {\n"
            "\tcc := make(chan chan int64, 1)\n"
            "\tcc <- p\n"
            "\treturn cc\n}\n"
        )
        uses = (
            "func Use(p chan int64, x int64) int64 {\n"
            "\tcc := G(p, x)\n"
            "\td := <-cc\n"
            "\td <- x\n"
            "\treturn <-d\n}\n"
        )
        inline = (
            "func Inline(p chan int64, x int64) int64 {\n"
            "\tcc := make(chan chan int64, 1)\n"
            "\tcc <- p\n"
            "\td := <-cc\n"
            "\td <- x\n"
            "\treturn <-d\n}\n"
        )
        compare = ("Use",)
        expected = frozenset({0, 1})
    elif variant in {
        "member-enqueued-before-send",
        "member-enqueued-after-send",
    }:
        member_send = (
            "\tcc <- c\n\tc <- x\n"
            if variant == "member-enqueued-before-send"
            else "\tc <- x\n\tcc <- c\n"
        )
        maker = (
            "func G(x int64) chan chan int64 {\n"
            + queue_setup
            + member_send
            + "\treturn cc\n}\n"
        )
        uses = (
            "func Use(x int64) int64 {\n"
            "\tcc := G(x)\n"
            "\td := <-cc\n"
            "\treturn <-d\n}\n"
        )
        inline = (
            "func Inline(x int64) int64 {\n"
            + queue_setup
            + member_send
            + "\td := <-cc\n"
            "\treturn <-d\n}\n"
        )
        compare = ("Use",)
        expected = frozenset({0})
    elif variant == "defer-after-return":
        maker = (
            "func Send(c chan int64, x int64) { c <- x }\n"
            "func G(x int64) chan chan int64 {\n"
            + queue_setup
            + "\tcc <- c\n"
            "\tdefer Send(c, x)\n"
            "\treturn cc\n}\n"
        )
        uses = (
            "func Use(x int64) int64 {\n"
            "\tcc := G(x)\n"
            "\td := <-cc\n"
            "\treturn <-d\n}\n"
        )
        inline = ""
        compare = ("Use",)
        expected = frozenset({0})
    else:
        raise AssertionError(variant)

    data = unit(go_types_helper, maker + uses + inline)
    source, snapshot, summaries = data
    maker_result = named(source, snapshot, summaries, "G")
    assert maker_result.available, (variant, maker_result.gaps)
    for function_name in compare:
        result = named(source, snapshot, summaries, function_name)
        expected_result = named(source, snapshot, summaries, "Inline") if inline else None
        assert result.available, (variant, function_name, result.gaps)
        if expected_result is not None:
            assert expected_result.available
            assert result.return_dependencies == expected_result.return_dependencies
            assert result.effects == "unknown"
        assert expected <= result.return_dependencies
    if variant == "direct":
        assert named(source, snapshot, summaries, "Direct").return_dependencies == frozenset({0})
        assert named(source, snapshot, summaries, "Bound").return_dependencies == frozenset({0})
    if variant == "defer-after-return":
        assert maker_result.effects == "unknown"


@pytest.mark.parametrize("imported", [False, True], ids=["package-var", "imported-var"])
def test_local_chan_chan_package_store_escapes_group(
    go_types_helper, imported
):
    if imported:
        files = {
            "a.go": 'package p\nimport "lib"\n'
            "func Store(x int64) {\n"
            "\tcc := make(chan chan int64, 1)\n"
            "\tc := make(chan int64, 1)\n"
            "\tcc <- c\n"
            "\tlib.V = cc\n"
            "\tc <- x\n"
            "}\n"
            "func Same(x int64) int64 {\n"
            "\tcc := make(chan chan int64, 1)\n"
            "\tc := make(chan int64, 1)\n"
            "\tcc <- c\n"
            "\tlib.V = cc\n"
            "\tc <- x\n"
            "\tlib.V = cc\n"
            "\td := <-lib.V\n"
            "\treturn <-d\n"
            "}\n"
            "func Read() int64 {\n"
            "\td := <-lib.V\n"
            "\treturn <-d\n"
            "}\n"
            "func Caller(x int64) int64 {\n"
            "\tStore(x)\n"
            "\td := <-lib.V\n"
            "\treturn <-d\n"
            "}\n",
        }
        imports = {"lib": {"lib.go": "package lib\nvar V chan chan int64\n"}}
        snapshot = load_go_package_snapshot(
            package_report_imports(go_types_helper, files, imports),
            files,
            target_arch="amd64",
        )
        summaries = ip.summarize_go_package(files, snapshot)
        names = {
            "Store": "Store",
            "Same": "Same",
            "Read": "Read",
            "Caller": "Caller",
        }
    else:
        files = {
            "a.go": "package p\nvar Global chan chan int64\n"
            "func Store(x int64) {\n"
            "\tcc := make(chan chan int64, 1)\n"
            "\tc := make(chan int64, 1)\n"
            "\tcc <- c\n"
            "\tGlobal = cc\n"
            "\tc <- x\n"
            "}\n"
            "func Same(x int64) int64 {\n"
            "\tcc := make(chan chan int64, 1)\n"
            "\tc := make(chan int64, 1)\n"
            "\tcc <- c\n"
            "\tGlobal = cc\n"
            "\tc <- x\n"
            "\tGlobal = cc\n"
            "\td := <-Global\n"
            "\treturn <-d\n"
            "}\n"
            "func Read() int64 {\n"
            "\td := <-Global\n"
            "\treturn <-d\n"
            "}\n"
            "func Caller(x int64) int64 {\n"
            "\tStore(x)\n"
            "\td := <-Global\n"
            "\treturn <-d\n"
            "}\n",
        }
        _, snapshot, summaries = package_unit(go_types_helper, files)
        names = {
            "Store": "Store",
            "Same": "Same",
            "Read": "Read",
            "Caller": "Caller",
        }

    store = named_package(files, snapshot, summaries, names["Store"])
    same = named_package(files, snapshot, summaries, names["Same"])
    read = named_package(files, snapshot, summaries, names["Read"])
    caller = named_package(files, snapshot, summaries, names["Caller"])
    assert store.available and store.effects == "unknown"
    assert same.available and same.return_dependencies == frozenset({0})
    assert same.effects == "unknown"
    assert read.available and read.effects == "unknown"
    assert caller.available and caller.return_dependencies == frozenset({0})
    assert caller.effects == "unknown"


def test_package_chan_chan_store_observes_later_member_sends(
    go_types_helper,
):
    source = (
        "var GCC chan chan int64\n"
        "func Same(x int64) int64 {\n"
        "\tcc := make(chan chan int64, 1)\n"
        "\tc := make(chan int64, 1)\n"
        "\tGCC = cc\n"
        "\tc <- x\n"
        "\tcc <- c\n"
        "\treturn <-(<-GCC)\n"
        "}\n"
        "func Store(x int64) {\n"
        "\tcc := make(chan chan int64, 1)\n"
        "\tc := make(chan int64, 1)\n"
        "\tGCC = cc\n"
        "\tc <- x\n"
        "\tcc <- c\n"
        "}\n"
        "func Read() int64 { return <-(<-GCC) }\n"
        "func Caller(x int64) int64 {\n"
        "\tStore(x)\n"
        "\td := <-GCC\n"
        "\treturn <-d\n"
        "}\n"
        "func JoinedBeforeSend(x int64) int64 {\n"
        "\tcc := make(chan chan int64, 1)\n"
        "\tc := make(chan int64, 1)\n"
        "\tGCC = cc\n"
        "\tcc <- c\n"
        "\tc <- x\n"
        "\treturn <-(<-GCC)\n"
        "}\n"
    )
    src, snapshot, summaries = unit(go_types_helper, source)
    for name in ("Same", "Caller", "JoinedBeforeSend"):
        result = named(src, snapshot, summaries, name)
        assert result.available, (name, result.gaps)
        assert result.return_dependencies == frozenset({0}), (
            name,
            result.return_dependencies,
        )
    read = named(src, snapshot, summaries, "Read")
    assert read.available and read.effects == "unknown"


