def test_deep_chan_chan_sent_nested_queue_promotes_external_group(
    go_types_helper,
):
    source = (
        "var GCCC chan chan chan int64\n"
        "var GCS []chan chan chan int64\n"
        "func F_depth2_direct(p chan chan int64, x int64) int64 {\n"
        "\tc := make(chan int64, 1)\n"
        "\tp <- c\n"
        "\tc <- x\n"
        "\treturn <-(<-p)\n"
        "}\n"
        "func F_depth2_named(p chan chan int64, x int64) int64 {\n"
        "\tc := make(chan int64, 1)\n"
        "\tp <- c\n"
        "\tc <- x\n"
        "\tq := <-p\n"
        "\treturn <-q\n"
        "}\n"
        "func F_param_direct(p chan chan chan int64, x int64) int64 {\n"
        "\tcc := make(chan chan int64, 1)\n"
        "\tc := make(chan int64, 1)\n"
        "\tcc <- c\n"
        "\tp <- cc\n"
        "\tc <- x\n"
        "\treturn <-(<-(<-p))\n"
        "}\n"
        "func F_param_named(p chan chan chan int64, x int64) int64 {\n"
        "\tcc := make(chan chan int64, 1)\n"
        "\tc := make(chan int64, 1)\n"
        "\tcc <- c\n"
        "\tp <- cc\n"
        "\tc <- x\n"
        "\tq := <-p\n"
        "\tr := <-q\n"
        "\treturn <-r\n"
        "}\n"
        "func F_package_direct(x int64) int64 {\n"
        "\tcc := make(chan chan int64, 1)\n"
        "\tc := make(chan int64, 1)\n"
        "\tcc <- c\n"
        "\tGCCC <- cc\n"
        "\tc <- x\n"
        "\treturn <-(<-(<-GCCC))\n"
        "}\n"
        "func F_package_named(x int64) int64 {\n"
        "\tcc := make(chan chan int64, 1)\n"
        "\tc := make(chan int64, 1)\n"
        "\tcc <- c\n"
        "\tGCCC <- cc\n"
        "\tc <- x\n"
        "\tq := <-GCCC\n"
        "\tr := <-q\n"
        "\treturn <-r\n"
        "}\n"
        "func F_container_direct(x int64) int64 {\n"
        "\tcc := make(chan chan int64, 1)\n"
        "\tc := make(chan int64, 1)\n"
        "\tcc <- c\n"
        "\tGCS[0] <- cc\n"
        "\tc <- x\n"
        "\treturn <-(<-(<-GCS[0]))\n"
        "}\n"
        "func F_container_named(x int64) int64 {\n"
        "\tcc := make(chan chan int64, 1)\n"
        "\tc := make(chan int64, 1)\n"
        "\tcc <- c\n"
        "\tGCS[0] <- cc\n"
        "\tc <- x\n"
        "\tq := <-GCS[0]\n"
        "\tr := <-q\n"
        "\treturn <-r\n"
        "}\n"
    )
    data = unit(go_types_helper, source)
    pairs = [
        ("F_depth2_direct", "F_depth2_named", frozenset({0, 1})),
        ("F_param_direct", "F_param_named", frozenset({0, 1})),
        ("F_package_direct", "F_package_named", frozenset({0})),
        ("F_container_direct", "F_container_named", frozenset({0})),
    ]
    mismatches = []
    for direct_name, named_name, expected_deps in pairs:
        direct = named(*data, direct_name)
        named_levels = named(*data, named_name)
        assert direct.available, direct.gaps
        assert named_levels.available, named_levels.gaps
        if direct.return_dependencies != named_levels.return_dependencies:
            mismatches.append(
                (
                    direct_name,
                    "named-equivalent",
                    direct.return_dependencies,
                    named_levels.return_dependencies,
                )
            )
        if direct.return_dependencies != expected_deps:
            mismatches.append(
                (
                    direct_name,
                    "expected",
                    direct.return_dependencies,
                    expected_deps,
                )
            )
        if direct.effects != named_levels.effects or direct.effects != "unknown":
            mismatches.append(
                (direct_name, "effects", direct.effects, named_levels.effects)
            )
    assert not mismatches, mismatches


def test_deep_chan_chan_nested_receive_evaluates_operands_once(
    go_types_helper,
):
    source = (
        "var GCCC chan chan chan int64\n"
        "var GCS []chan chan chan int64\n"
        "var GI chan int64\n"
        "func G() chan chan chan int64 {\n"
        "\tclose(GCCC)\n"
        "\treturn GCCC\n"
        "}\n"
        "func I() int {\n"
        "\tclose(GI)\n"
        "\treturn 0\n"
        "}\n"
        "func F_call_direct() int64 {\n"
        "\treturn <-(<-(<-G()))\n"
        "}\n"
        "func F_call_named() int64 {\n"
        "\tq := G()\n"
        "\tnext := <-q\n"
        "\tvalue := <-next\n"
        "\treturn <-value\n"
        "}\n"
        "func F_index_direct() int64 {\n"
        "\treturn <-(<-(<-GCS[I()]))\n"
        "}\n"
        "func F_index_named() int64 {\n"
        "\ti := I()\n"
        "\treturn <-(<-(<-GCS[i]))\n"
        "}\n"
    )
    data = unit(go_types_helper, source)
    mismatches = []
    for direct_name, named_name in [
        ("F_call_direct", "F_call_named"),
        ("F_index_direct", "F_index_named"),
    ]:
        direct = named(*data, direct_name)
        named_levels = named(*data, named_name)
        assert direct.available, direct.gaps
        assert named_levels.available, named_levels.gaps
        direct_transfers = len(direct.calls)
        named_transfers = len(named_levels.calls)
        if direct_transfers != named_transfers:
            mismatches.append(
                (direct_name, direct_transfers, named_transfers)
            )
    assert not mismatches, mismatches


def test_deep_chan_chan_var_comma_ok_matches_short_declaration(
    go_types_helper,
):
    source = (
        "func F_external_var(p chan chan chan int64) int64 {\n"
        "\tvar q2, ok = <-p\n"
        "\tif !ok { return 0 }\n"
        "\treturn <-(<-q2)\n"
        "}\n"
        "func F_external_short(p chan chan chan int64) int64 {\n"
        "\tq2, ok := <-p\n"
        "\tif !ok { return 0 }\n"
        "\treturn <-(<-q2)\n"
        "}\n"
        "func F_local_var(x int64) int64 {\n"
        "\tc := make(chan int64, 1)\n"
        "\tc <- x\n"
        "\tcc := make(chan chan int64, 1)\n"
        "\tcc <- c\n"
        "\tccc := make(chan chan chan int64, 1)\n"
        "\tccc <- cc\n"
        "\tvar q2, ok = <-ccc\n"
        "\tif !ok { return 0 }\n"
        "\treturn <-(<-q2)\n"
        "}\n"
        "func F_local_short(x int64) int64 {\n"
        "\tc := make(chan int64, 1)\n"
        "\tc <- x\n"
        "\tcc := make(chan chan int64, 1)\n"
        "\tcc <- c\n"
        "\tccc := make(chan chan chan int64, 1)\n"
        "\tccc <- cc\n"
        "\tq2, ok := <-ccc\n"
        "\tif !ok { return 0 }\n"
        "\treturn <-(<-q2)\n"
        "}\n"
    )
    data = unit(go_types_helper, source)
    mismatches = []
    for var_name, short_name, expected_deps, expected_effects in [
        (
            "F_external_var",
            "F_external_short",
            frozenset({0}),
            "unknown",
        ),
        (
            "F_local_var",
            "F_local_short",
            frozenset({0}),
            "none_in_supported_fragment",
        ),
    ]:
        var_result = named(*data, var_name)
        short_result = named(*data, short_name)
        if not var_result.available or not short_result.available:
            mismatches.append(
                (
                    var_name,
                    var_result.gaps,
                    short_name,
                    short_result.gaps,
                )
            )
            continue
        if (
            var_result.return_dependencies
            != short_result.return_dependencies
            or var_result.return_dependencies != expected_deps
            or var_result.effects != short_result.effects
            or var_result.effects != expected_effects
        ):
            mismatches.append(
                (
                    var_name,
                    var_result.return_dependencies,
                    var_result.effects,
                    short_name,
                    short_result.return_dependencies,
                    short_result.effects,
                )
            )
    assert not mismatches, mismatches


