@pytest.mark.parametrize(
    "declarations",
    [
        # `[][]chan` nests stay closed — the operand of the inner
        # index is itself an index expression.
        "var GS [][]chan int64\nfunc F(x int64) {\n\tGS[0][0] <- x\n}\n",
        # A second index into a nested element container stays closed.
        "var GS [][]chan int64\nfunc F() int64 {\n\td := GS[0][0]\n\treturn <-d\n}\n",
        # Comma-ok map extraction remains closed.
        "var GM map[int64]chan int64\nfunc F(k int64) int64 {\n\td, ok := GM[k]\n"
        "\tif ok { return <-d }\n\treturn 0\n}\n",
        # Function-literal calls with extracted channel arguments stay closed.
        "var GS []chan int64\nfunc F(x int64) int64 {\n"
        "\tfunc(c chan int64) { c <- x }(GS[0])\n"
        "\treturn <-GS[0]\n}\n",
        # A closure capturing an extracted name stays closed, like a
        # captured `d := GC`.
        "var GS []chan int64\nfunc F(x int64) int64 {\n"
        "\td := GS[0]\n\tgo func() { d <- x }()\n"
        "\treturn <-GS[0]\n}\n",
    ],
)
def test_chan_elem_external_unsupported_stays_closed(
    go_types_helper, declarations
):
    result = named(*unit(go_types_helper, declarations))
    assert not result.available


@pytest.mark.parametrize(
    ("declarations", "expected"),
    [
        # `s = append(s, c2)` — the appended queue joins the
        # result's share group like a `[]chan{c}` literal seed:
        # `c2 <- x` reaches `<-s[1]`.
        (
            "func F(x int64) int64 {\n"
            "\tc1 := make(chan int64, 4)\n"
            "\tc2 := make(chan int64, 4)\n"
            "\ts := []chan int64{c1}\n"
            "\ts = append(s, c2)\n"
            "\tc2 <- x\n"
            "\treturn <-s[1]\n}\n",
            frozenset({0}),
        ),
        # `b := append(s, c2)` — the bound result's group holds the
        # appended queue the same way.
        (
            "func F(x int64) int64 {\n"
            "\tc1 := make(chan int64, 4)\n"
            "\tc2 := make(chan int64, 4)\n"
            "\ts := []chan int64{c1}\n"
            "\tb := append(s, c2)\n"
            "\tc2 <- x\n"
            "\treturn <-b[1]\n}\n",
            frozenset({0}),
        ),
        # A send THROUGH the appended element lands in the group —
        # `<-c2` observes it like a `[]chan{c2}` member read.
        (
            "func F(x int64) int64 {\n"
            "\tc1 := make(chan int64, 4)\n"
            "\tc2 := make(chan int64, 4)\n"
            "\ts := []chan int64{c1}\n"
            "\ts = append(s, c2)\n"
            "\ts[1] <- x\n"
            "\treturn <-c2\n}\n",
            frozenset({0}),
        ),
        # `b := s` before the append — the result may reuse `s`'s
        # backing, so `b`'s group gains the appended queue too.
        (
            "func F(x int64) int64 {\n"
            "\tc1 := make(chan int64, 4)\n"
            "\tc2 := make(chan int64, 4)\n"
            "\ts := []chan int64{c1}\n"
            "\tb := s\n"
            "\ts = append(s, c2)\n"
            "\tc2 <- x\n"
            "\treturn <-b[0]\n}\n",
            frozenset({0}),
        ),
        # A param queue appended in — the external member's send
        # records the caller-visible effect and the read conflates
        # the ordinal like any group receive.
        (
            "func F(c2 chan int64, x int64) int64 {\n"
            "\tc1 := make(chan int64, 4)\n"
            "\ts := []chan int64{c1}\n"
            "\ts = append(s, c2)\n"
            "\tc2 <- x\n"
            "\treturn <-s[1]\n}\n",
            frozenset({0, 1}),
        ),
        # `var s = append(s0, c2)` binds like `s :=`.
        (
            "func F(x int64) int64 {\n"
            "\tc1 := make(chan int64, 4)\n"
            "\tc2 := make(chan int64, 4)\n"
            "\ts0 := []chan int64{c1}\n"
            "\tvar s = append(s0, c2)\n"
            "\tc2 <- x\n"
            "\treturn <-s[1]\n}\n",
            frozenset({0}),
        ),
        # `s[i] = c2` element store already joined the queue —
        # `append` carrying a second queue adds it too.
        (
            "func F(x int64) int64 {\n"
            "\tc1 := make(chan int64, 4)\n"
            "\tc2 := make(chan int64, 4)\n"
            "\tc3 := make(chan int64, 4)\n"
            "\ts := []chan int64{c1}\n"
            "\ts[0] = c2\n"
            "\ts = append(s, c3)\n"
            "\tc3 <- x\n"
            "\treturn <-s[1]\n}\n",
            frozenset({0}),
        ),
        # `s = append(s, t[0])` — an element-expression extra joins
        # the source container's member queues the same way.
        (
            "func F(x int64) int64 {\n"
            "\tc1 := make(chan int64, 4)\n"
            "\tc2 := make(chan int64, 4)\n"
            "\ts := []chan int64{c1}\n"
            "\tt := []chan int64{c2}\n"
            "\ts = append(s, t[0])\n"
            "\tc2 <- x\n"
            "\treturn <-s[1]\n}\n",
            frozenset({0}),
        ),
        # The send direction through an element-expression extra:
        # `s[1] <- x` deposits into `t`'s member queues too.
        (
            "func F(x int64) int64 {\n"
            "\tc1 := make(chan int64, 4)\n"
            "\tc2 := make(chan int64, 4)\n"
            "\ts := []chan int64{c1}\n"
            "\tt := []chan int64{c2}\n"
            "\ts = append(s, t[0])\n"
            "\ts[1] <- x\n"
            "\treturn <-c2\n}\n",
            frozenset({0}),
        ),
        # `c, s = make(chan), append(s, c)` — the pre-state `c` the
        # append named is the OLD queue: the reseat parks it under
        # a surrogate so the send on `c1`'s sibling member still
        # reaches `<-s[1]`, and a send INTO `s[1]` lands on the old
        # queue an earlier alias keeps.
        (
            "func F(x int64) int64 {\n"
            "\tc1 := make(chan int64, 4)\n"
            "\tc := make(chan int64, 4)\n"
            "\ts := []chan int64{c1}\n"
            "\te := c\n"
            "\tc, s = make(chan int64, 4), append(s, c)\n"
            "\ts[1] <- x\n"
            "\treturn <-e\n}\n",
            frozenset({0}),
        ),
        # Same parallel reseat — `<-c` reads the FRESH queue: the
        # send through `s[1]` went to the parked old one.
        (
            "func F(x int64) int64 {\n"
            "\tc1 := make(chan int64, 4)\n"
            "\tc := make(chan int64, 4)\n"
            "\ts := []chan int64{c1}\n"
            "\tc, s = make(chan int64, 4), append(s, c)\n"
            "\ts[1] <- x\n"
            "\treturn <-c\n}\n",
            frozenset(),
        ),
        # And the other order stays correct — the append's member
        # joins before `c` reseats, so `s[0]`'s sends reach `<-s[1]`
        # and `s[1]`'s send reaches the old queue via its member.
        (
            "func F(x int64) int64 {\n"
            "\tc1 := make(chan int64, 4)\n"
            "\tc := make(chan int64, 4)\n"
            "\ts := []chan int64{c1}\n"
            "\ts, c = append(s, c), make(chan int64, 4)\n"
            "\tc1 <- x\n"
            "\treturn <-s[1]\n}\n",
            frozenset({0}),
        ),
        # `t, s = u, append(s, t[0])` — the appended element's
        # members are `t`'s PRE-state group (`c2`), not the `u`
        # members `t` lands on: `c3 <- x` must not reach `<-s[1]`
        # and `s[1] <- x` must not reach `<-c3`.
        (
            "func F(x int64) int64 {\n"
            "\tc1 := make(chan int64, 4)\n"
            "\tc2 := make(chan int64, 4)\n"
            "\tc3 := make(chan int64, 4)\n"
            "\ts := []chan int64{c1}\n"
            "\tt := []chan int64{c2}\n"
            "\tu := []chan int64{c3}\n"
            "\tt, s = u, append(s, t[0])\n"
            "\tc2 <- x\n"
            "\treturn <-s[1]\n}\n",
            frozenset({0}),
        ),
        (
            "func F(x int64) int64 {\n"
            "\tc1 := make(chan int64, 4)\n"
            "\tc2 := make(chan int64, 4)\n"
            "\tc3 := make(chan int64, 4)\n"
            "\ts := []chan int64{c1}\n"
            "\tt := []chan int64{c2}\n"
            "\tu := []chan int64{c3}\n"
            "\tt, s = u, append(s, t[0])\n"
            "\tc3 <- x\n"
            "\treturn <-s[1]\n}\n",
            frozenset(),
        ),
        (
            "func F(x int64) int64 {\n"
            "\tc1 := make(chan int64, 4)\n"
            "\tc2 := make(chan int64, 4)\n"
            "\tc3 := make(chan int64, 4)\n"
            "\ts := []chan int64{c1}\n"
            "\tt := []chan int64{c2}\n"
            "\tu := []chan int64{c3}\n"
            "\tt, s = u, append(s, t[0])\n"
            "\ts[1] <- x\n"
            "\treturn <-c3\n}\n",
            frozenset(),
        ),
        # `b := s` then `s = u` — the surrogate that parks `s`'s
        # old group for `b` keeps the OLD dep set; the reseated
        # value's deps must not leak into `<-b[0]`.
        (
            "func F(u []chan int64, x int64) int64 {\n"
            "\tc1 := make(chan int64, 4)\n"
            "\ts := []chan int64{c1}\n"
            "\tb := s\n"
            "\ts = u\n"
            "\treturn <-b[0]\n}\n",
            frozenset(),
        ),
        (
            "func F(u []chan int64, x int64) int64 {\n"
            "\tc1 := make(chan int64, 4)\n"
            "\ts := []chan int64{c1}\n"
            "\tb := s\n"
            "\ts = u\n"
            "\tc1 <- x\n"
            "\treturn <-b[0]\n}\n",
            frozenset({1}),
        ),
    ],
)
def test_chan_elem_append(go_types_helper, declarations, expected):
    result = named(*unit(go_types_helper, declarations))
    assert result.available
    assert result.return_dependencies == expected


def test_chan_elem_append_param_transfer(go_types_helper):
    # `s = append(s, c2)` with a param queue — `c2 <- x` is a
    # caller-visible effect: an imported transfer lands on the
    # param's identity.
    declarations = (
        "func F(c2 chan int64, x int64) int64 {\n"
        "\ts := []chan int64{make(chan int64, 1)}\n"
        "\ts = append(s, c2)\n"
        "\tc2 <- x\n"
        "\treturn 0\n}\n"
    )
    source, snapshot, summaries = unit(go_types_helper, declarations)
    result = named(source, snapshot, summaries)
    assert result.available
    c2 = next(b for b in snapshot.bindings if b.name == "c2")
    assert any(t.imported and t.target == c2.id for t in result.calls)


@pytest.mark.parametrize(
    ("declarations", "expected"),
    [
        # `s.V = <-ch` — a field store on a local composite folds the
        # receive into the base binding like the plain assignment.
        (
            "func F(ch chan int64) int64 {\n"
            "\tvar s struct{ V int64 }\n"
            "\tselect {\n"
            "\tcase s.V = <-ch:\n"
            "\t\treturn s.V\n"
            "\t}\n"
            "\treturn 0\n}\n",
            frozenset({0}),
        ),
        # `*p = <-ch` — a bound-pointer store lands in untracked
        # memory: the deps fold into escaped bindings and
        # `indirect_writes`, so a later `*p` read observes them.
        (
            "func F(ch chan int64, p *int64) int64 {\n"
            "\tselect {\n"
            "\tcase *p = <-ch:\n"
            "\t}\n"
            "\treturn *p\n}\n",
            frozenset({0, 1}),
        ),
        # `*p = <-ch` may aim at an escaped local — `return y`
        # observes the receive.
        (
            "func F(ch chan int64) int64 {\n"
            "\tvar y int64\n"
            "\tp := &y\n"
            "\tselect {\n"
            "\tcase *p = <-ch:\n"
            "\t}\n"
            "\treturn y\n}\n",
            frozenset({0}),
        ),
    ],
)
def test_select_composite_receive_stores(go_types_helper, declarations, expected):
    result = named(*unit(go_types_helper, declarations))
    assert result.available and result.return_dependencies == expected


