    # bound-literal path: `y` gains `v`'s deps.
    source, snapshot, summaries = unit(
        go_types_helper,
        "func F(x int64) int64 {\n"
        "    v := x; var y int64\n"
        "    fs := []func(){func(){ y = v }}\n"
        "    fs[0]()\n"
        "    return y\n"
        "}",
    )
    result = named(source, snapshot, summaries)
    assert result.available
    assert result.return_dependencies == frozenset({0})


